"""Generate native/polyglot_random.h from python-chess's random array.

Pulling the 781 constants straight from python-chess guarantees the C Zobrist
hash uses byte-identical constants, so the only thing left to match is the
algorithm. Re-run if python-chess ever changes the array (it won't; it's the
fixed Polyglot book spec).
"""

from pathlib import Path

import chess.polyglot

arr = chess.polyglot.POLYGLOT_RANDOM_ARRAY
assert len(arr) == 781, len(arr)

out = Path(__file__).with_name("polyglot_random.h")
lines = [
    "// Generated by gen_polyglot_header.py from python-chess. Do not edit.",
    "// 781 Polyglot Zobrist constants (indices 0-767 pieces, 768-771 castling,",
    "// 772-779 en-passant files, 780 turn).",
    "#pragma once",
    "#include <stdint.h>",
    "",
    "static const uint64_t POLYGLOT_RANDOM[781] = {",
]
for i in range(0, 781, 4):
    chunk = ", ".join(f"{v}ULL" for v in arr[i : i + 4])
    lines.append(f"    {chunk},")
lines.append("};")
out.write_text("\n".join(lines) + "\n")
print(f"wrote {out} ({len(arr)} constants)")
